{"policy_source":"from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes):
        self.capacity = max(0, int(capacity_bytes))
        self.probation = OrderedDict()
        self.protected = OrderedDict()
        self.ghost_probation = OrderedDict()
        self.ghost_protected = OrderedDict()
        self.probation_bytes = 0
        self.protected_bytes = 0
        self.ghost_bytes = 0
        self.probation_target = self.capacity // 2
        self.ghost_limit = max(64, min(1 << 20, 2 * max(1, self.capacity)))
        self.ghost_count_limit = 4096
        self.serial = 0

    def _drop_ghost(self, key):
        for ghosts in (self.ghost_probation, self.ghost_protected):
            value = ghosts.pop(key, None)
            if value is not None:
                self.ghost_bytes -= value[0]

    def _remember_ghost(self, key, size, kind):
        self._drop_ghost(key)
        self.serial += 1
        value = (size, self.serial)
        ghosts = self.ghost_probation if kind == 1 else self.ghost_protected
        ghosts[key] = value
        self.ghost_bytes += size
        self._trim_ghosts()

    def _trim_ghosts(self):
        while self.ghost_bytes > self.ghost_limit or len(self.ghost_probation) + len(self.ghost_protected) > self.ghost_count_limit:
            choices = []
            if self.ghost_probation:
                choices.append((next(iter(self.ghost_probation.items()))[1][1], self.ghost_probation))
            if self.ghost_protected:
                choices.append((next(iter(self.ghost_protected.items()))[1][1], self.ghost_protected))
            _, ghosts = min(choices, key=lambda item: item[0])
            _, value = ghosts.popitem(last=False)
            self.ghost_bytes -= value[0]

    def _adjust_target(self, kind):
        if self.capacity <= 0:
            return
        if kind == 1:
            a, b = self._ghost_bytes(1), self._ghost_bytes(2)
            step = self.capacity if a == 0 else max(1, min(self.capacity, b // a or 1))
            self.probation_target = min(self.capacity, self.probation_target + step)
        else:
            a, b = self._ghost_bytes(1), self._ghost_bytes(2)
            step = self.capacity if b == 0 else max(1, min(self.capacity, a // b or 1))
            self.probation_target = max(0, self.probation_target - step)

    def _ghost_bytes(self, kind):
        ghosts = self.ghost_probation if kind == 1 else self.ghost_protected
        return sum(value[0] for value in ghosts.values())

    def _evict_one(self, prefer_probation):
        ghosts = None
        if prefer_probation and self.probation:
            ghosts = self.probation
            kind = 1
        elif self.protected:
            ghosts = self.protected
            kind = 2
        elif self.probation:
            ghosts = self.probation
            kind = 1
        else:
            return None
        key, size = ghosts.popitem(last=False)
        if kind == 1:
            self.probation_bytes -= size
        else:
            self.protected_bytes -= size
        self._remember_ghost(key, size, kind)
        return key

    def _make_room(self, incoming, ghost_kind):
        evicted = []
        while self.probation_bytes + self.protected_bytes + incoming > self.capacity:
            prefer = bool(self.probation) and (self.probation_bytes > self.probation_target or (ghost_kind == 2 and self.probation_bytes == self.probation_target))
            victim = self._evict_one(prefer)
            if victim is None:
                break
            evicted.append(victim)
        return evicted

    def access(self, key, size, now):
        key = int(key)
        size = max(0, int(size))
        resident = key in self.probation or key in self.protected
        if resident:
            if key in self.probation:
                old = self.probation.pop(key)
                self.probation_bytes -= old
            else:
                old = self.protected.pop(key)
                self.protected_bytes -= old
            if size <= 0 or size > self.capacity:
                return []
            evicted = self._make_room(size, 0)
            self.protected[key] = size
            self.protected_bytes += size
            return evicted
        ghost_kind = 1 if key in self.ghost_probation else 2 if key in self.ghost_protected else 0
        if size <= 0 or size > self.capacity:
            return []
        if ghost_kind:
            self._adjust_target(ghost_kind)
            self._drop_ghost(key)
        evicted = self._make_room(size, ghost_kind)
        if ghost_kind:
            self.protected[key] = size
            self.protected_bytes += size
        else:
            self.probation[key] = size
            self.probation_bytes += size
        return evicted
